    const res = await fetch(`${WORKER_URL}${path}`, {
        ...options,
        headers: {
            'Content-Type': 'application/json',
            ...(WORKER_TOKEN ? { 'X-Worker-Token': WORKER_TOKEN } : {}),
            ...(options.headers || {}),
        },
    });
    if (!res.ok) {
