  --ink-900: #111113;
  --ink-850: #17171a;
  --ink-800: #1c1c1f;
  --ink-700: #2a2a2e;
  --ink-600: #3a3a3f;
  --ink-500: #4d4d54;

  /* --- Примитивы: статусы (системные цвета iOS, тёмная схема) ------------ */
  --ios-green: #30d158;
  --ios-orange: #ff9f0a;
  --ios-red: #ff453a;
  --ios-blue: #0a84ff;

  /* --- Материалы ---------------------------------------------------------
     Заливка + размытие подложки. Заливка светлеющая: в тёмной схеме iOS
     материал не затемняет фон, а поднимает его. Saturate возвращает цвет,
     который размытие съедает, — без него стекло выглядит грязным. */
  --material-ultrathin: rgba(255, 255, 255, 0.04);
  --material-thin: rgba(255, 255, 255, 0.06);
  --material-regular: rgba(255, 255, 255, 0.08);
  --material-thick: rgba(255, 255, 255, 0.11);

  /* Хром — наоборот, притемняющий: панели должны читаться как рама, а не как
     ещё один лист контента. */
  --material-chrome: rgba(0, 0, 0, 0.55);
  --material-chrome-strong: rgba(0, 0, 0, 0.74);

