  --blur-md: blur(32px) saturate(170%);
  --blur-lg: blur(48px) saturate(180%);

  /* --- Семантика: поверхности ------------------------------------------- */
  --bg: var(--ink-1000);
  --surface: var(--material-ultrathin);
  --surface-raised: var(--material-thin);
  --surface-overlay: var(--material-regular);
  --surface-sunken: rgba(0, 0, 0, 0.32);
  --control: rgba(255, 255, 255, 0.07);
  --control-hover: rgba(255, 255, 255, 0.12);
  --control-active: rgba(255, 255, 255, 0.16);

  /* Непрозрачные варианты для перетаскиваемых и всплывающих элементов:
     стекло поверх стекла превращается в кашу. */
  --surface-solid: var(--ink-850);
  --surface-solid-raised: var(--ink-800);

  /* --- Семантика: текст --------------------------------------------------
     Метки iOS: белый с падающей альфой. На любом материале дают одинаковую
     иерархию, потому что смешиваются с тем, что под ними. Альфа поднята
     относительно системных значений Apple: те не держат 4.5:1 на светлых
     участках фоновой среды. */
  --text: rgba(255, 255, 255, 0.96);
  --text-secondary: rgba(235, 235, 245, 0.8);
  --text-tertiary: rgba(235, 235, 245, 0.6);
  --text-quaternary: rgba(235, 235, 245, 0.3);
  --text-on-accent: var(--ink-1000);

  /* --- Семантика: границы ------------------------------------------------
     Волосяная линия iOS: светлая сверху, гасящаяся книзу. */
  --border: rgba(255, 255, 255, 0.09);
  --border-subtle: rgba(255, 255, 255, 0.055);
  --border-strong: rgba(255, 255, 255, 0.16);
  --hairline-top: inset 0 1px 0 rgba(255, 255, 255, 0.07);

  /* --- Семантика: акцент -------------------------------------------------
     Акцент монохромный. Действие выделяется не цветом, а плотностью
     материала и контрастом: главная кнопка — единственная белая плоскость
     на экране, и этого достаточно. */
  --accent: var(--white);
  --accent-strong: var(--white);
  --accent-text: var(--white);
  --accent-rgb: 255, 255, 255;
  --accent-surface: rgba(255, 255, 255, 0.12);
  --accent-surface-hover: rgba(255, 255, 255, 0.18);
  --accent-border: rgba(255, 255, 255, 0.24);

  /* --- Семантика: статусы ------------------------------------------------
     Цвет остаётся только там, где он несёт смысл: успех, риск, ошибка. */
  --success: var(--ios-green);
  --success-surface: rgba(48, 209, 88, 0.14);
  --success-border: rgba(48, 209, 88, 0.28);
  --warning: var(--ios-orange);
  --warning-surface: rgba(255, 159, 10, 0.14);
  --warning-border: rgba(255, 159, 10, 0.28);
  --danger: var(--ios-red);
  --danger-strong: var(--ios-red);
  --danger-surface: rgba(255, 69, 58, 0.14);
  --danger-border: rgba(255, 69, 58, 0.3);
  --info: var(--ios-blue);
  --info-surface: rgba(10, 132, 255, 0.14);
  --info-border: rgba(10, 132, 255, 0.28);

  /* Совместимость: отдельные компоненты обращаются к оттенкам напрямую. */
  --rose-300: #ff8f88;
  --rose-500: var(--ios-red);
  --emerald-300: #6ee7b7;
  --amber-300: #ffcf70;
  --sky-300: #6cb8ff;
  --gray-500: rgba(235, 235, 245, 0.34);

